/**
 * Check if a given object implements the CashFlowDataSupplementalData interface.
 */
export function instanceOfCashFlowDataSupplementalData(value) {
    return true;
}
export function CashFlowDataSupplementalDataFromJSON(json) {
    return CashFlowDataSupplementalDataFromJSONTyped(json, false);
}
export function CashFlowDataSupplementalDataFromJSONTyped(json, ignoreDiscriminator) {
    if (json == null) {
        return json;
    }
    return {
        interestPaidSupplementalData: json["interest_paid_supplemental_data"] == null
            ? undefined
            : json["interest_paid_supplemental_data"],
        incomeTaxPaidSupplementalData: json["income_tax_paid_supplemental_data"] == null
            ? undefined
            : json["income_tax_paid_supplemental_data"],
    };
}
export function CashFlowDataSupplementalDataToJSON(json) {
    return CashFlowDataSupplementalDataToJSONTyped(json, false);
}
export function CashFlowDataSupplementalDataToJSONTyped(value, ignoreDiscriminator = false) {
    if (value == null) {
        return value;
    }
    return {
        interest_paid_supplemental_data: value["interestPaidSupplementalData"],
        income_tax_paid_supplemental_data: value["incomeTaxPaidSupplementalData"],
    };
}
